<?= $this->extend('admin/layout') ?><?= $this->section('content') ?>
<?php $labels = ['pages' => 'Pages', 'services' => 'Services', 'projects' => 'Projects', 'news' => 'News']; $newUrl = $tab === 'pages' ? site_url('admin/pages/new') : site_url('admin/content/new'); ?>
<div class="cms-content"><header class="cms-list-head"><div><h1>Pages &amp; posts</h1><p>Create, update and publish everything visitors see on the website.</p></div><a class="cms-primary" href="<?= $newUrl ?>">＋ New <?= strtolower(rtrim($labels[$tab], 's')) ?></a></header>
<nav class="cms-tabs" aria-label="Content type"><?php foreach ($labels as $key => $label): ?><a class="<?= $tab === $key ? 'active' : '' ?>" href="<?= site_url('admin/pages?tab=' . $key) ?>"><?= $label ?><span class="tab-count"><?= $counts[$key] ?></span></a><?php endforeach ?></nav>
<div class="cms-table-wrap"><table class="cms-table"><thead><tr><th>Title</th><th>URL</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if (! $items): ?><tr><td class="cms-empty" colspan="5">No <?= strtolower($labels[$tab]) ?> yet. Create your first one to get started.</td></tr><?php endif ?><?php foreach ($items as $item): ?><?php $image = $tab === 'pages' ? ($item['hero_image'] ?? '') : ($item['cover_image'] ?? ''); $edit = $tab === 'pages' ? site_url('admin/pages/' . $item['id'] . '/edit') : site_url('admin/content/' . $item['id'] . '/edit'); $delete = $tab === 'pages' ? site_url('admin/pages/' . $item['id'] . '/delete') : site_url('admin/content/' . $item['id'] . '/delete'); ?>
<tr><td><span class="cms-row-title"><span class="cms-row-thumb" style="background-image:url('<?= esc(base_url($image ?: 'assets/images/palm-plantation.jpg'), 'attr') ?>')"></span><span><?= esc($item['title']) ?><small><?= $tab === 'pages' ? 'Page' : esc(ucfirst($item['type'])) ?></small></span></span></td><td>/<?= esc($item['slug']) ?></td><td><span class="cms-status <?= $item['status'] === 'draft' ? 'draft' : '' ?>"><?= esc($item['status']) ?></span></td><td><?= esc(date('d M Y', strtotime($item['updated_at']))) ?></td><td><span class="cms-row-actions"><a href="<?= $edit ?>">Edit</a><form method="post" action="<?= $delete ?>" onsubmit="return confirm('Delete this item?')"><?= csrf_field() ?><button>Delete</button></form></span></td></tr><?php endforeach ?></tbody></table></div></div>
<?= $this->endSection() ?>
